(() => {
'use strict';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cities=[
{id:'oi',code:'RIO',pt:'Rio de Janeiro',name:'Рио-де-Жанейро',note:'Город на побережье Атлантики. Начни знакомство с простого приветствия.'},
{id:'origem',code:'SP',pt:'São Paulo',name:'Сан-Паулу',note:'Большой город на юго-востоке Бразилии. Потренируйся рассказывать, откуда ты.'},
{id:'nome',code:'SSA',pt:'Salvador',name:'Салвадор',note:'Столица штата Баия. Здесь начнём знакомство с имени.'},
{id:'estar',code:'BSB',pt:'Brasília',name:'Бразилиа',note:'Столица Бразилии. Скажи, как ты себя чувствуешь сегодня.'},
{id:'ter',code:'REC',pt:'Recife',name:'Ресифи',note:'Город на северо-востоке страны. Потренируй короткую бытовую фразу.'},
{id:'rotina',code:'CWB',pt:'Curitiba',name:'Куритиба',note:'Столица штата Парана на юге Бразилии. Расскажи о своём обычном дне.'},
{id:'gostar',code:'FLN',pt:'Florianópolis',name:'Флорианополис',note:'Город на юге Бразилии. Расскажи, что тебе нравится.'},
{id:'compras',code:'MAO',pt:'Manaus',name:'Манаус',note:'Столица штата Амазонас. Здесь пригодится вопрос о покупке.'},
{id:'cafe',code:'BEL',pt:'Belém',name:'Белен',note:'Столица штата Пара на севере страны. Потренируй заказ в кафе.'},
{id:'horas',code:'FOR',pt:'Fortaleza',name:'Форталеза',note:'Город на северо-восточном побережье. Научись уточнять время.'},
{id:'artigos',code:'OP',pt:'Ouro Preto',name:'Ору-Прету',note:'Город в штате Минас-Жерайс. Разберись с маленькими словами перед существительными.'},
{id:'numeros',code:'IGU',pt:'Foz do Iguaçu',name:'Фос-ду-Игуасу',note:'Город на юге Бразилии, рядом с водопадами Игуасу. Потренируй числа.'}
];
let mode='lessons',zoom=1,selected='oi';
function reset(){mode='lessons';zoom=1;selected='oi'}
function city(){return mode==='cities'?cities.find(c=>c.id===selected)||cities[0]:null}
function panel(m,points,pin){const exploring=mode==='cities',dots=exploring?window.BoraJourney.layout(cities.map(c=>c.id)):points;return '<div class="atlas-map-panel"><div class="atlas-controls"><div class="atlas-modes" aria-label="Что показать на карте"><button data-map-mode="lessons" aria-pressed="'+!exploring+'">Мои занятия</button><button data-map-mode="cities" aria-pressed="'+exploring+'">Города</button></div><div class="atlas-zoom" aria-label="Масштаб карты"><button data-map-zoom="-1" aria-label="Уменьшить карту" '+(zoom===1?'disabled':'')+'>−</button><button data-map-reset aria-label="Вернуть исходный масштаб">'+Math.round(zoom*100)+'%</button><button data-map-zoom="1" aria-label="Увеличить карту" '+(zoom===3?'disabled':'')+'>+</button></div></div><div class="atlas-viewport" tabindex="0" aria-label="Карта Бразилии. После увеличения прокручивай карту в нужную сторону."><div class="atlas-map" style="--map-zoom:'+zoom+'"><svg viewBox="0 0 600 600" aria-hidden="true"><path class="atlas-country" d="'+window.BoraMapData.path+'"/>'+(!exploring?'<path class="atlas-route" d="M'+dots.map(p=>p.point.join(',')).join(' L')+'"/>':'')+dots.map(p=>'<path class="atlas-leader" d="M'+p.anchor.join(',')+' L'+p.point.join(',')+'"/><circle class="atlas-location" cx="'+p.anchor[0]+'" cy="'+p.anchor[1]+'" r="3"/>').join('')+'<text x="66" y="280" class="atlas-country-name">BRASIL</text><text x="440" y="500" class="atlas-ocean">АТЛАНТИКА</text></svg>'+dots.map((p,i)=>exploring?'<button type="button" class="atlas-pin city-pin '+(p.id===selected?'is-selected':'')+'" data-city="'+esc(p.id)+'" aria-label="'+esc(cities[i].name)+'" aria-pressed="'+(p.id===selected)+'" style="left:'+p.point[0]/6+'%;top:'+p.point[1]/6+'%">'+esc(cities[i].code)+(zoom>=1.5?'<span class="city-map-label">'+esc(cities[i].name)+'</span>':'')+'</button>':pin(p,i)).join('')+'</div></div><div class="atlas-map-key">'+(exploring?'<span>12 городов для знакомства</span>':'<span><i class="key-done"></i>Пройдено</span><span><i class="key-selected"></i>Выбрано</span>')+'<span>'+(zoom>1?'Прокручивай карту пальцем':'Увеличь карту, чтобы рассмотреть')+'</span></div>'+(exploring?'<details class="atlas-city-list"><summary>Выбрать город из списка</summary><div>'+cities.map(c=>'<button data-city="'+c.id+'" aria-pressed="'+(c.id===selected)+'">'+esc(c.name)+'</button>').join('')+'</div></details>':'')+'</div>';}
function card(){const c=city();if(!c)return '';const l=window.BoraCourses[0].lessons.find(l=>l.id===c.id),photo=window.BoraLessonPhotos[c.id];return '<article class="journey-stop city-card"><div class="journey-photo"><img src="'+esc(photo.src)+'" alt="'+esc(c.name)+'" width="640" height="360"><span>Знакомство с Бразилией</span></div><div class="journey-stop-body"><h2>'+esc(c.name)+'</h2><p class="city-portuguese" lang="pt-BR">'+esc(c.pt)+'</p><p>'+esc(c.note)+'</p><div class="city-phrase"><strong lang="pt-BR">'+esc(l.examples[0][0])+'</strong><span>'+esc(l.examples[0][1])+'</span>'+window.BoraKit.audio(l.examples[0][0])+'</div><a class="btn journey-start" href="#unit/'+c.id+'">'+esc(l.title)+' →</a><audio id="kit-player" hidden controls preload="none"></audio><p id="kit-audio-status" role="status"></p></div></article>';}
function bind(render){if(!document.querySelector('.atlas-viewport'))return;const redraw=(change,selector)=>{const pane=document.querySelector('.atlas-viewport'),x=(pane.scrollLeft+pane.clientWidth/2)/(pane.scrollWidth||1),y=(pane.scrollTop+pane.clientHeight/2)/(pane.scrollHeight||1);change();render();const fresh=document.querySelector('.atlas-viewport');if(fresh){fresh.scrollLeft=x*fresh.scrollWidth-fresh.clientWidth/2;fresh.scrollTop=y*fresh.scrollHeight-fresh.clientHeight/2;}document.querySelector(selector)?.focus({preventScroll:true})};document.querySelectorAll('[data-map-mode]').forEach(b=>b.onclick=()=>redraw(()=>{mode=b.dataset.mapMode},'[data-map-mode="'+b.dataset.mapMode+'"]'));document.querySelectorAll('[data-map-zoom]').forEach(b=>b.onclick=()=>redraw(()=>{zoom=Math.max(1,Math.min(3,zoom+Number(b.dataset.mapZoom)*.5))},'[data-map-zoom="'+b.dataset.mapZoom+'"]'));document.querySelector('[data-map-reset]').onclick=()=>redraw(()=>zoom=1,'[data-map-reset]');document.querySelectorAll('[data-city]').forEach(b=>b.onclick=e=>{redraw(()=>selected=b.dataset.city,'.atlas-map [data-city="'+b.dataset.city+'"]');if(e.detail>0&&window.matchMedia?.('(max-width:760px)').matches)document.querySelector('.city-card')?.scrollIntoView({block:'start',behavior:'instant'})});}
window.BoraExplore={cities,reset,city,panel,card,bind};
})();
